import {WEAPONS,weaponConfig} from './weapons.js';
import {SOUND_TYPES} from './spatial-audio.js';
import {LEVELS} from './core.js';
const playerFields=['id','name','weaponLevel','roundWins','knockouts','kills','points','played','weapon','x','y','z','vx','vy','vz','runBoost','fireBoost','jumpBoost','courseStep','grounded','crouching','courseDuckEntry','yaw','pitch','cameraDistance','visualShotSpeed','hp','score','total','attempt','respawn','invuln','throwCD','catchCD','catchTime','dashCD','dashTime','dashX','dashZ','shotAnim','shotDuration','pendingThrow','gun','mag','reload','runner'];
export function packPlayer(p){return{...Object.fromEntries(playerFields.map(k=>[k,p[k]??(k==='shotDuration'?.46:k==='cameraDistance'?4.6:k==='visualShotSpeed'?weaponConfig(p).speed:0)])),best:Number.isFinite(p.best)?p.best:null,checks:[...p.checks]};}
export function unpackPlayer(p){if(!p||!Number.isInteger(p.id)||p.id<0||p.id>3)return null;const out={};for(const k of playerFields){if(k==='name')out.name=String(p.name??'SPUD').replace(/[^\p{L}\p{M}0-9 '’_-]/gu,'').slice(0,24);else if(k==='weapon'){if(!['throw','spud','repeater','scatter','masher','rpg'].includes(p.weapon))return null;out.weapon=p.weapon;}else if(['gun','runner','grounded','crouching'].includes(k))out[k]=p[k]===true;else if(!Number.isFinite(p[k]))return null;else out[k]=p[k];}out.best=Number.isFinite(p.best)?p.best:Infinity;out.checks=[p.checks?.[0]===true,p.checks?.[1]===true];return out;}
export function validSnapshot(s){return s&&s.version===10&&Number.isInteger(s.circuitSeed)&&s.circuitSeed>=0&&s.circuitSeed<=100000&&typeof s.circuitId==='string'&&Array.isArray(s.history)&&s.history.length<=LEVELS.length&&s.history.every(r=>typeof r.epoch==='string'&&Number.isInteger(r.level)&&r.level>=0&&r.level<LEVELS.length&&Number.isFinite(r.duration)&&Array.isArray(r.winners)&&Array.isArray(r.players)&&[3,4].includes(r.players.length)&&r.players.every(p=>Number.isFinite(p.total)&&Number.isFinite(p.knockouts)))&&Number.isInteger(s.seq)&&typeof s.epoch==='string'&&Number.isInteger(s.levelIndex)&&s.levelIndex>=0&&s.levelIndex<LEVELS.length&&Array.isArray(s.players)&&[3,4].includes(s.players.length)&&s.players.every((p,i)=>p.id===i&&unpackPlayer(p))&&['playing','results'].includes(s.state)&&Number.isFinite(s.remaining)&&Number.isFinite(s.time)&&Number.isFinite(s.intro)&&Array.isArray(s.shots)&&s.shots.length<400&&s.shots.every(p=>['id','owner','x','y','z','vx','vy','vz','age','damage'].every(k=>Number.isFinite(p[k])))&&Array.isArray(s.targets)&&s.targets.length<=14&&s.targets.every(t=>Number.isFinite(t.hp)&&Number.isFinite(t.respawn))&&validPickups(s)&&validAudio(s)&&Array.isArray(s.penalty)&&s.penalty.every(i=>Number.isInteger(i)&&i>=0&&i<4)&&Number.isFinite(s.activeDuration)&&s.activeDuration>=40&&s.activeDuration<=600;}
function validPickups(s){if(!Array.isArray(s.pickups)||s.pickups.length>7||new Set(s.pickups.map(p=>p.id)).size!==s.pickups.length||s.pickups.filter(p=>p.kind==='weapon').length>1)return false;return s.pickups.every(p=>{if(!Number.isInteger(p.id)||!Number.isFinite(p.x)||!Number.isFinite(p.z)||Math.abs(p.x)>150||Math.abs(p.z)>150||p.owner!==-1||typeof p.collected!=='boolean'||!Number.isFinite(p.respawn)||p.respawn<0||!['run','fire','jump','weapon'].includes(p.kind))return false;if(p.kind!=='weapon')return true;const w=WEAPONS[p.weapon];if(!w||p.weapon==='spud'||!Number.isInteger(p.ammo)||p.ammo<0||p.ammo>w.ammo)return false;if(p.phase==='available')return p.ammo>0&&p.holder===-1&&!p.collected;if(p.phase==='spent')return p.ammo===0&&p.holder===-1&&p.collected;if(p.phase!=='held'||!Number.isInteger(p.holder)||p.holder<0||p.holder>3||!p.collected||p.ammo<=0)return false;const holder=s.players[p.holder];return holder.weapon===p.weapon&&holder.mag===p.ammo&&holder.respawn<=0;});}
function validAudio(s){let last=0;return Array.isArray(s.audioEvents)&&s.audioEvents.length<=128&&s.audioEvents.every(e=>{if(!Number.isInteger(e.id)||e.id<=last||!SOUND_TYPES.has(e.type)||!['x','y','z','time'].every(k=>Number.isFinite(e[k]))||Math.abs(e.x)>150||Math.abs(e.z)>150||Math.abs(e.y)>30||e.time>s.time+.1||s.time-e.time>2)return false;last=e.id;return true;});}
export function remoteControl(packet,p,epoch,edges,age,now=globalThis.performance.now()){const idle={x:0,z:0,fire:false,catch:false,dodge:false,jump:false,crouch:false};if(!packet||packet.epoch!==epoch||age>500)return idle;
 const n=(v,a,b)=>Number.isFinite(v)?Math.max(a,Math.min(b,v)):0;
 p.cameraDistance=Number.isFinite(packet.zoom)?n(packet.zoom,3,9):4.6;p.yaw=n(packet.yaw,-100000,100000);p.pitch=n(packet.pitch,-.85,.70);
 const crouchSerial=n(packet.crouchSerial,0,1e12);if(crouchSerial>(edges.crouch??0)){edges.crouchUntil=now+70;edges.crouch=crouchSerial;}
 const output={x:n(packet.x,-1,1),z:n(packet.z,-1,1),fire:packet.fire===true,crouch:packet.crouch===true||now<(edges.crouchUntil??0),dodge:false,catch:false,jump:false};edges.crouch=Math.max(packet.crouchSerial??0,edges.crouch??0);for(const k of['dodge','catch','jump']){const counter=n(packet[k],0,1e12);output[k]=counter>(edges[k]??0);edges[k]=Math.max(counter,edges[k]??0);}return output;
}
